SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, PERCENTILE_APPROX(amount, 0.5) AS amount_p50, COUNT_IF(txn_type = 'FEE') AS fee_events, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(amount, 0.9) AS amount_p90, SUM(CASE WHEN txn_type = 'DEBIT' THEN amount ELSE 0 END) AS debit_amount FROM transactions GROUP BY year_start HAVING COUNT_IF(txn_type = 'FEE') < 1 ORDER BY debit_amount DESC NULLS LAST
